terminal equ 0x40
indicator equ 0x10
tries equ tries_text + 6
ldi c, title
ldi d, wait
text_start:
  ldi b, terminal
  st b, out
  text_loop:
    ld a, c
    or a, 0
    jz d
    st a, b
    inc c
    jmp text_loop
wait:
  ld a, in
  or a, 0
  jz wait
start:
  ldi a, 0x30
  st a, tries
guess_num:
  rnd a
  ldi b, 98
  sub b, a
  jc guess_num
  inc a
  st a, num
try:
  ld a, tries
  inc a
  ldi b, 0x37
  xor b, a
  jz lose
  st a, tries
  ldi c, tries_text
  ldi d, num1
  jmp text_start
space:
  ldi c, 0x20
  st c, output
  jmp cmp
void db 0, 0, 0, 0, 0
num db 0
lives db 5
in db 0
out db indicator
output db 5
num1:
  exp c
  st c, in
  ld a, in
  mov c, a
  ldi b, 0x31
  sub a, b
  jc num1
  inc a
  ldi b, 9
  sub b, a
  jc num1
  st c, output
  mov d, a
num2:
  exp c
  st c, in
  ld a, in
  ldi c, 0x0A
  xor c, a
  jz space
  mov c, a
  ldi b, 0x30
  sub a, b
  jc num2
  ldi b, 9
  sub b, a
  jc num2
  st c, output
mul:
  mov b, a
  mov a, d
  shl d
  shl d
  add d, a
  shl d
  mov a, b
  add d, a
cmp:
  ld a, num
  sub a, d
  jz win
  jc lower
higher:
  ldi c, higher_text
  ldi d, try
  jmp text_start
lower:
  ldi c, lower_text
  ldi d, try
  jmp text_start
win:
  ldi c, win_text
  ldi d, start
  jmp text_start
lose:
  ldi c, lose_text
  ldi d, start
  ldi a, indicator
  st a, out
  ld a, lives
  dec a
  st a, lives
  st a, output
  jnz text_start
  ldi d, end
  jmp text_start
end:
  hlt
title db 0x47, 0x4D, 0x4E, 0x20, 0x62,
0x65, 0x72, 0x20, 0x31, 0x85, 0x39,
0x39, 0x20, 0x69, 0x6E, 0x20, 0x36,
0x20, 0x74, 0x72, 0x69, 0x65, 0x73, 0x2E, 0
tries_text db 0x20, 0x20, 0x54, 0x72, 0x79, 0x20, 0x30, 0x3A, 0
higher_text db  0x20, 0x20, 0x68, 0x69, 0x67, 0x68, 0x65, 0x72, 0
lower_text db 0x20, 0x20, 0x20, 0x6C, 0x6F, 0x77, 0x65, 0x72, 0
win_text db 0x59, 0x6F, 0x75, 0x20, 0x77, 0x69, 0x6E, 0x21, 0
lose_text db 0x59, 0x6F, 0x75, 0x20, 0x6C, 0x6F, 0x73, 0x65, 0


